 77→    private TrieSSTableReader(SSTableMetadata metadata, KeyIndex keyIndex, BloomFilter bloomFilter,
 78→            long dataEnd, byte[] eagerData, SeekableByteChannel lazyChannel, BlockCache blockCache,
 79→            CompressionMap compressionMap, Map<Byte, CompressionCodec> codecMap) {
 80→        this.metadata = metadata;
 81→        this.keyIndex = keyIndex;
 82→        this.bloomFilter = bloomFilter;
 83→        this.dataEnd = dataEnd;
 84→        this.eagerData = eagerData;
 85→        this.lazyChannel = lazyChannel;
 86→        this.blockCache = blockCache;
