 98→    public static TrieSSTableReader open(Path path, BloomFilter.Deserializer bloomDeserializer,
 99→            BlockCache blockCache) throws IOException {
100→        Objects.requireNonNull(path, "path must not be null");
101→        Objects.requireNonNull(bloomDeserializer, "bloomDeserializer must not be null");
102→
103→        SeekableByteChannel ch = Files.newByteChannel(path, StandardOpenOption.READ);
104→        try {
105→            long fileSize = ch.size();
106→            Footer footer = readFooterV1(ch, fileSize);
107→            KeyIndex keyIndex = readKeyIndexV1(ch, footer);
108→            BloomFilter bloom = readBloomFilter(ch, footer, bloomDeserializer);
109→            SSTableMetadata meta = buildMetadata(path, fileSize, footer, keyIndex);
110→
111→            // Read entire data region eagerly
112→            int dataLen = (int) footer.idxOffset;
113→            byte[] data = readBytes(ch, 0L, dataLen);
