152→    /**
153→     * Opens an SSTable file eagerly, with support for both v1 and v2 (compressed) formats.
154→     *
155→     * @param path path to the SSTable file
156→     * @param bloomDeserializer deserializer for the bloom filter
157→     * @param blockCache optional block cache, or null
158→     * @param codecs compression codecs available for decompression; for v2 files, all codec IDs
159→     *            used in the file must be represented
160→     * @return a new reader
161→     * @throws IOException if the file cannot be read or contains an unknown codec ID
162→     */
163→    public static TrieSSTableReader open(Path path, BloomFilter.Deserializer bloomDeserializer,
164→            BlockCache blockCache, CompressionCodec... codecs) throws IOException {
165→        Objects.requireNonNull(path, "path must not be null");
166→        Objects.requireNonNull(bloomDeserializer, "bloomDeserializer must not be null");
167→        Objects.requireNonNull(codecs, "codecs must not be null");
168→
169→        SeekableByteChannel ch = Files.newByteChannel(path, StandardOpenOption.READ);
170→        try {
171→            long fileSize = ch.size();
172→            Footer footer = readFooter(ch, fileSize);
173→
174→            CompressionMap compressionMap = null;
175→            Map<Byte, CompressionCodec> codecMap = null;
176→            long dataEnd;
177→            KeyIndex keyIndex;
178→
179→            if (footer.version == 2) {
180→                byte[] mapBytes = readBytes(ch, footer.mapOffset, (int) footer.mapLength);
181→                compressionMap = CompressionMap.deserialize(mapBytes);
