183→                validateCodecMap(compressionMap, codecMap);
184→                keyIndex = readKeyIndexV2(ch, footer);
185→                dataEnd = footer.mapOffset;
186→            } else {
187→                keyIndex = readKeyIndexV1(ch, footer);
188→                dataEnd = footer.idxOffset;
189→            }
190→
191→            BloomFilter bloom = readBloomFilter(ch, footer, bloomDeserializer);
192→            SSTableMetadata meta = buildMetadata(path, fileSize, footer, keyIndex);
193→
194→            int dataLen = (int) dataEnd;
195→            byte[] data = readBytes(ch, 0L, dataLen);
196→            ch.close();
197→
198→            return new TrieSSTableReader(meta, keyIndex, bloom, dataEnd, data, null, blockCache,
199→                    compressionMap, codecMap);
