262→    @Override
263→    public Optional<Entry> get(MemorySegment key) throws IOException {
264→        Objects.requireNonNull(key, "key must not be null");
265→        checkNotClosed();
266→
267→        if (!bloomFilter.mightContain(key)) {
268→            return Optional.empty();
269→        }
270→
271→        Optional<Long> offsetOpt = keyIndex.lookup(key);
272→        if (offsetOpt.isEmpty()) {
273→            return Optional.empty();
274→        }
275→
276→        long offset = offsetOpt.get();
277→
278→        if (compressionMap != null) {
279→            // v2: offset is packed (blockIndex << 32 | intraBlockOffset)
280→            int blockIndex = (int) (offset >>> 32);
281→            int intraBlockOffset = (int) offset;
282→            byte[] decompressedBlock = readAndDecompressBlock(blockIndex);
283→            return Optional.of(EntryCodec.decode(decompressedBlock, intraBlockOffset));
284→        } else {
285→            // v1: offset is absolute file position
286→            byte[] entryBytes = readDataAtV1(offset, SSTableFormat.DEFAULT_BLOCK_SIZE);
287→            return Optional.of(EntryCodec.decode(entryBytes, 0));
288→        }
289→    }
