291→    @Override
292→    public Iterator<Entry> scan() throws IOException {
293→        checkNotClosed();
294→        if (compressionMap != null) {
295→            // v2: decompress all blocks and iterate
296→            byte[] allData = decompressAllBlocks();
297→            return new DataRegionIterator(allData, allData.length);
298→        } else {
299→            // v1: iterate raw data region
300→            byte[] data = getAllDataV1();
301→            return new DataRegionIterator(data, dataEnd);
302→        }
303→    }
