325→    /**
326→     * Reads and decompresses a single block by index using the compression map.
327→     */
328→    private byte[] readAndDecompressBlock(int blockIndex) throws IOException {
329→        assert compressionMap != null : "readAndDecompressBlock called on v1 reader";
330→        assert codecMap != null : "codecMap must not be null for v2";
331→
332→        CompressionMap.Entry mapEntry = compressionMap.entry(blockIndex);
333→
334→        if (blockCache != null) {
335→            Optional<MemorySegment> hit = blockCache.get(metadata.id(), blockIndex);
336→            if (hit.isPresent()) {
337→                return hit.get().toArray(ValueLayout.JAVA_BYTE);
338→            }
339→        }
340→
341→        byte[] compressed;
342→        if (eagerData != null) {
343→            compressed = new byte[mapEntry.compressedSize()];
344→            System.arraycopy(eagerData, (int) mapEntry.blockOffset(), compressed, 0,
345→                    mapEntry.compressedSize());
346→        } else {
347→            compressed = readBytes(lazyChannel, mapEntry.blockOffset(), mapEntry.compressedSize());
348→        }
349→
350→        CompressionCodec codec = codecMap.get(mapEntry.codecId());
351→        assert codec != null : "codec not found for ID 0x%02x".formatted(mapEntry.codecId());
352→        byte[] decompressed = codec.decompress(compressed, 0, compressed.length,
353→                mapEntry.uncompressedSize());
354→
355→        if (blockCache != null) {
356→            blockCache.put(metadata.id(), blockIndex, MemorySegment.ofArray(decompressed));
357→        }
358→
359→        return decompressed;
360→    }
361→
362→    /**
363→     * Decompresses all blocks and concatenates them into a single byte array for full scan.
364→     */
365→    private byte[] decompressAllBlocks() throws IOException {
366→        assert compressionMap != null : "decompressAllBlocks called on v1 reader";
367→        int totalUncompressed = 0;
368→        for (int i = 0; i < compressionMap.blockCount(); i++) {
369→            totalUncompressed += compressionMap.entry(i).uncompressedSize();
370→        }
371→        byte[] result = new byte[totalUncompressed];
372→        int off = 0;
373→        for (int i = 0; i < compressionMap.blockCount(); i++) {
374→            byte[] block = readAndDecompressBlock(i);
375→            System.arraycopy(block, 0, result, off, block.length);
376→            off += block.length;
377→        }
378→        assert off == totalUncompressed : "decompressed size mismatch";
379→        return result;
380→    }
