382→    private static Map<Byte, CompressionCodec> buildCodecMap(CompressionCodec... codecs) {
383→        Map<Byte, CompressionCodec> map = new HashMap<>();
384→        for (CompressionCodec codec : codecs) {
385→            map.put(codec.codecId(), codec);
386→        }
387→        return Collections.unmodifiableMap(map);
388→    }
