390→    private static void validateCodecMap(CompressionMap compressionMap,
391→            Map<Byte, CompressionCodec> codecMap) throws IOException {
392→        for (int i = 0; i < compressionMap.blockCount(); i++) {
393→            byte codecId = compressionMap.entry(i).codecId();
394→            if (!codecMap.containsKey(codecId)) {
395→                throw new IOException(
396→                        "unknown compression codec ID 0x%02x in block %d; available codecs: %s"
397→                                .formatted(codecId, i, codecMap.keySet()));
398→            }
399→        }
400→    }
