409→    /** Returns the data at {@code fileOffset} (v1 absolute offset), reading at most maxBytes. */
410→    private byte[] readDataAtV1(long fileOffset, int maxBytes) throws IOException {
411→        int len = (int) Math.min(maxBytes, dataEnd - fileOffset);
412→        if (len <= 0)
413→            throw new IOException("file offset out of data range: " + fileOffset);
414→
415→        if (blockCache != null) {
416→            Optional<MemorySegment> hit = blockCache.get(metadata.id(), fileOffset);
417→            if (hit.isPresent()) {
418→                return hit.get().toArray(ValueLayout.JAVA_BYTE);
419→            }
420→        }
421→
422→        byte[] data;
423→        if (eagerData != null) {
424→            data = new byte[len];
425→            System.arraycopy(eagerData, (int) fileOffset, data, 0, len);
426→        } else {
427→            data = readBytes(lazyChannel, fileOffset, len);
428→        }
429→
430→        if (blockCache != null) {
431→            blockCache.put(metadata.id(), fileOffset, MemorySegment.ofArray(data));
432→        }
433→        return data;
434→    }
