449→    /** Reads a v1-only footer. Throws on v2 magic. */
450→    private static Footer readFooterV1(SeekableByteChannel ch, long fileSize) throws IOException {
451→        if (fileSize < SSTableFormat.FOOTER_SIZE) {
452→            throw new IOException("not a valid SSTable file: too small");
453→        }
454→        byte[] buf = readBytes(ch, fileSize - SSTableFormat.FOOTER_SIZE, SSTableFormat.FOOTER_SIZE);
455→        long idxOffset = readLong(buf, 0);
456→        long idxLength = readLong(buf, 8);
457→        long fltOffset = readLong(buf, 16);
458→        long fltLength = readLong(buf, 24);
459→        long entryCount = readLong(buf, 32);
460→        long magic = readLong(buf, 40);
461→        if (magic != SSTableFormat.MAGIC) {
462→            throw new IOException("not a valid SSTable file: bad magic " + Long.toHexString(magic));
463→        }
464→        return new Footer(1, 0, 0, idxOffset, idxLength, fltOffset, fltLength, entryCount);
465→    }
