467→    /** Reads footer detecting v1 or v2 format from magic bytes. */
468→    private static Footer readFooter(SeekableByteChannel ch, long fileSize) throws IOException {
469→        if (fileSize < SSTableFormat.FOOTER_SIZE) {
470→            throw new IOException("not a valid SSTable file: too small");
471→        }
472→        // Read the last 8 bytes to check magic
473→        byte[] magicBuf = readBytes(ch, fileSize - 8, 8);
474→        long magic = readLong(magicBuf, 0);
475→
476→        if (magic == SSTableFormat.MAGIC_V2) {
477→            if (fileSize < SSTableFormat.FOOTER_SIZE_V2) {
478→                throw new IOException("not a valid v2 SSTable file: too small");
479→            }
480→            byte[] buf = readBytes(ch, fileSize - SSTableFormat.FOOTER_SIZE_V2,
481→                    SSTableFormat.FOOTER_SIZE_V2);
482→            long mapOffset = readLong(buf, 0);
483→            long mapLength = readLong(buf, 8);
484→            long idxOffset = readLong(buf, 16);
485→            long idxLength = readLong(buf, 24);
486→            long fltOffset = readLong(buf, 32);
487→            long fltLength = readLong(buf, 40);
488→            long entryCount = readLong(buf, 48);
489→            return new Footer(2, mapOffset, mapLength, idxOffset, idxLength, fltOffset, fltLength,
490→                    entryCount);
491→        } else if (magic == SSTableFormat.MAGIC) {
492→            byte[] buf = readBytes(ch, fileSize - SSTableFormat.FOOTER_SIZE,
493→                    SSTableFormat.FOOTER_SIZE);
494→            long idxOffset = readLong(buf, 0);
495→            long idxLength = readLong(buf, 8);
496→            long fltOffset = readLong(buf, 16);
497→            long fltLength = readLong(buf, 24);
498→            long entryCount = readLong(buf, 32);
499→            return new Footer(1, 0, 0, idxOffset, idxLength, fltOffset, fltLength, entryCount);
500→        } else {
501→            throw new IOException("not a valid SSTable file: bad magic " + Long.toHexString(magic));
502→        }
503→    }
