505→    /** Reads v1 key index: [numKeys(4)][per key: keyLen(4) + key + fileOffset(8)]. */
506→    private static KeyIndex readKeyIndexV1(SeekableByteChannel ch, Footer footer)
507→            throws IOException {
508→        byte[] buf = readBytes(ch, footer.idxOffset, (int) footer.idxLength);
509→        int numKeys = readInt(buf, 0);
510→        List<MemorySegment> keys = new ArrayList<>(numKeys);
511→        List<Long> offsets = new ArrayList<>(numKeys);
512→        int off = 4;
513→        for (int i = 0; i < numKeys; i++) {
514→            int keyLen = readInt(buf, off);
515→            off += 4;
516→            byte[] keyBytes = new byte[keyLen];
517→            System.arraycopy(buf, off, keyBytes, 0, keyLen);
518→            off += keyLen;
519→            long fileOffset = readLong(buf, off);
520→            off += 8;
521→            keys.add(MemorySegment.ofArray(keyBytes));
522→            offsets.add(fileOffset);
523→        }
524→        return new KeyIndex(keys, offsets);
525→    }
