527→    /** Reads v2 key index: [numKeys(4)][per key: keyLen(4) + key + blockIndex(4) + intraOff(4)]. */
528→    private static KeyIndex readKeyIndexV2(SeekableByteChannel ch, Footer footer)
529→            throws IOException {
530→        byte[] buf = readBytes(ch, footer.idxOffset, (int) footer.idxLength);
531→        int numKeys = readInt(buf, 0);
532→        List<MemorySegment> keys = new ArrayList<>(numKeys);
533→        List<Long> offsets = new ArrayList<>(numKeys);
534→        int off = 4;
535→        for (int i = 0; i < numKeys; i++) {
536→            int keyLen = readInt(buf, off);
537→            off += 4;
538→            byte[] keyBytes = new byte[keyLen];
539→            System.arraycopy(buf, off, keyBytes, 0, keyLen);
540→            off += keyLen;
541→            int blockIndex = readInt(buf, off);
542→            off += 4;
543→            int intraBlockOffset = readInt(buf, off);
544→            off += 4;
545→            // Pack into a single long, same encoding as the writer
546→            long packed = ((long) blockIndex << 32) | (intraBlockOffset & 0xFFFFFFFFL);
547→            keys.add(MemorySegment.ofArray(keyBytes));
548→            offsets.add(packed);
549→        }
550→        return new KeyIndex(keys, offsets);
551→    }
