553→    private static BloomFilter readBloomFilter(SeekableByteChannel ch, Footer footer,
554→            BloomFilter.Deserializer deserializer) throws IOException {
555→        byte[] buf = readBytes(ch, footer.fltOffset, (int) footer.fltLength);
556→        // Use an Arena-allocated segment to satisfy the alignment constraints of the deserializer
557→        // (BlockedBloomFilter uses JAVA_INT/JAVA_LONG without withByteAlignment(1)).
558→        try (Arena arena = Arena.ofShared()) {
559→            MemorySegment seg = arena.allocate(buf.length, 8);
560→            MemorySegment.copy(MemorySegment.ofArray(buf), 0, seg, 0, buf.length);
561→            return deserializer.deserialize(seg);
562→        }
563→    }
