565→    private static SSTableMetadata buildMetadata(Path path, long fileSize, Footer footer,
566→            KeyIndex keyIndex) {
567→        MemorySegment smallestKey = null;
568→        MemorySegment largestKey = null;
569→        Iterator<KeyIndex.Entry> it = keyIndex.iterator();
570→        while (it.hasNext()) {
571→            KeyIndex.Entry e = it.next();
572→            if (smallestKey == null)
573→                smallestKey = e.key();
574→            largestKey = e.key();
575→        }
576→        assert smallestKey != null : "key index must not be empty when building metadata";
577→        return new SSTableMetadata(0L, path, Level.L0, smallestKey, largestKey, SequenceNumber.ZERO,
578→                SequenceNumber.ZERO, fileSize, footer.entryCount);
579→    }
