581→    // ---- Low-level I/O ----
582→
583→    private static byte[] readBytes(SeekableByteChannel ch, long offset, int length)
584→            throws IOException {
585→        if (length == 0)
586→            return new byte[0];
587→        ByteBuffer buf = ByteBuffer.allocate(length);
588→        ch.position(offset);
589→        while (buf.hasRemaining()) {
590→            int read = ch.read(buf);
591→            if (read < 0)
592→                throw new IOException("unexpected EOF at offset " + (offset + buf.position()));
593→        }
594→        return buf.array();
595→    }
596→
597→    private static int readInt(byte[] buf, int off) {
598→        return ((buf[off] & 0xFF) << 24) | ((buf[off + 1] & 0xFF) << 16)
599→                | ((buf[off + 2] & 0xFF) << 8) | (buf[off + 3] & 0xFF);
600→    }
601→
602→    private static long readLong(byte[] buf, int off) {
603→        return ((long) (buf[off] & 0xFF) << 56) | ((long) (buf[off + 1] & 0xFF) << 48)
604→                | ((long) (buf[off + 2] & 0xFF) << 40) | ((long) (buf[off + 3] & 0xFF) << 32)
605→                | ((long) (buf[off + 4] & 0xFF) << 24) | ((long) (buf[off + 5] & 0xFF) << 16)
606→                | ((long) (buf[off + 6] & 0xFF) << 8) | (long) (buf[off + 7] & 0xFF);
607→    }
