609→    // ---- Iterators ----
610→
611→    /**
612→     * Iterates entries by parsing the raw data region linearly (block by block). Parses: [int
613→     * count][entry...][int count][entry...]... until offset reaches dataEnd.
614→     */
615→    private static final class DataRegionIterator implements Iterator<Entry> {
616→        private final byte[] data;
617→        private final long dataEnd;
618→        private int offset = 0;
619→        private List<Entry> blockEntries = new ArrayList<>();
620→        private int entryIdx = 0;
621→        private Entry next;
622→
623→        DataRegionIterator(byte[] data, long dataEnd) {
624→            this.data = data;
625→            this.dataEnd = dataEnd;
626→            advance();
627→        }
628→
629→        private void advance() {
630→            next = null;
631→            while (true) {
632→                if (entryIdx < blockEntries.size()) {
633→                    next = blockEntries.get(entryIdx++);
634→                    return;
635→                }
636→                if (offset >= dataEnd)
637→                    return;
638→                // Parse next block
639→                int count = readInt(data, offset);
640→                offset += 4;
641→                blockEntries = new ArrayList<>(count);
642→                for (int i = 0; i < count; i++) {
643→                    Entry e = EntryCodec.decode(data, offset);
644→                    blockEntries.add(e);
645→                    offset += EntryCodec.encodedSize(e);
646→                }
647→                entryIdx = 0;
648→            }
649→        }
650→
651→        @Override
652→        public boolean hasNext() {
653→            return next != null;
654→        }
655→
656→        @Override
657→        public Entry next() {
658→            if (next == null)
659→                throw new NoSuchElementException();
660→            Entry result = next;
661→            advance();
662→            return result;
663→        }
664→
665→        private static int readInt(byte[] buf, int off) {
666→            return ((buf[off] & 0xFF) << 24) | ((buf[off + 1] & 0xFF) << 16)
667→                    | ((buf[off + 2] & 0xFF) << 8) | (buf[off + 3] & 0xFF);
668→        }
669→    }
