671→    /**
672→     * Iterates entries via key index range results, reading each entry at its offset. Handles both
673→     * v1 (absolute file offset) and v2 (packed blockIndex + intraBlockOffset) formats.
674→     */
675→    private final class IndexRangeIterator implements Iterator<Entry> {
676→        private final Iterator<KeyIndex.Entry> indexIter;
677→        private Entry next;
678→
679→        IndexRangeIterator(Iterator<KeyIndex.Entry> indexIter) {
680→            this.indexIter = indexIter;
681→            advance();
682→        }
683→
684→        private void advance() {
685→            next = null;
686→            if (!indexIter.hasNext())
687→                return;
688→            KeyIndex.Entry ie = indexIter.next();
689→            try {
690→                if (compressionMap != null) {
691→                    // v2: unpack (blockIndex, intraBlockOffset) and decompress
692→                    long packed = ie.fileOffset();
693→                    int blockIndex = (int) (packed >>> 32);
694→                    int intraBlockOffset = (int) packed;
695→                    byte[] block = readAndDecompressBlock(blockIndex);
696→                    next = EntryCodec.decode(block, intraBlockOffset);
697→                } else {
698→                    // v1: read at absolute file offset
699→                    byte[] buf = readDataAtV1(ie.fileOffset(), SSTableFormat.DEFAULT_BLOCK_SIZE);
700→                    next = EntryCodec.decode(buf, 0);
701→                }
702→            } catch (IOException e) {
703→                throw new UncheckedIOException(e);
704→            }
705→        }
706→
707→        @Override
708→        public boolean hasNext() {
709→            return next != null;
710→        }
711→
712→        @Override
713→        public Entry next() {
714→            if (next == null)
715→                throw new NoSuchElementException();
716→            Entry result = next;
717→            advance();
718→            return result;
719→        }
720→    }
721→}
